// Build the SOP §6 Gmail + signature nudge — branches on onboarder_type.
// Inbound payload (from Next.js fireOnboardingTemplate):
//   { onboarderId, template:'gmail-signature-nudge', event, context: {
//     onboarder_type ('contractor'|'intern'), full_name, first_name, personal_email,
//     role_title, onboarding_lead
//   } }

const body = ($input.first().json.body ?? $input.first().json);
const ctx  = body.context || {};
const type            = ctx.onboarder_type   || 'contractor';
const toEmail         = ctx.personal_email   || body.to;
const firstName       = ctx.first_name       || (ctx.full_name || 'there').split(' ')[0];
const onboardingLead  = ctx.onboarding_lead  || 'Erich';

if (!toEmail) {
  throw new Error('No personal_email on context — cannot send Gmail nudge');
}

const subject = 'Set up your Romega email | Next step';

let body_;
if (type === 'intern') {
  body_ = `Hi ${firstName},

For the next step, please create a Gmail account to serve as your official Romega work email. Make sure the account is fully set up and functioning properly.

Use the following format: [FirstInitial][FullLastName].romegasolutions@gmail.com
Example: John Smith → jsmith.romegasolutions@gmail.com

Once it's done, just shoot me a message with the email address!

Once complete, please create your personal Romega email signature here:
https://romega-email-signature.vercel.app/

Cheers,
${onboardingLead}
Onboarding Lead, Romega Solutions`;
} else {
  body_ = `Hi ${firstName},

For the next step of your onboarding, please create a Gmail account to serve as your official Romega work email. Make sure the account is fully set up and functioning properly.

Use the following format: [FirstName]@romega-solutions.com
Example: john@romega-solutions.com

Once done, just shoot me a message with the email address.

We'll handle the signature setup with you on Teams once your Romega Gmail is live.

Cheers,
${onboardingLead}
Onboarding Lead, Romega Solutions`;
}

return [{ json: { to: toEmail, subject, body: body_, onboarderId: body.onboarderId, template: 'gmail-signature-nudge', onboarderType: type } }];
